using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(cb => cb
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<NoteService>();
builder.Services.AddSingleton<ResearchTools>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

// Build the agent with tools
var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    "You are a research assistant. Use the web_search tool to find information about the topic. " +
    "Use the add_note tool to record key findings as you go. " +
    "After researching, use get_notes to review what you've collected, then provide a concise summary.");

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and summarize your findings: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = [
            AIFunctionFactory.Create(researchTools.WebSearch),
            AIFunctionFactory.Create(researchTools.AddNote),
            AIFunctionFactory.Create(researchTools.GetNotes),
        ],
    },
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n✅ Research complete.");

// Show collected notes
var noteService = host.Services.GetRequiredService<NoteService>();
var notes = noteService.GetAll();
if (notes.Count > 0)
{
    Console.WriteLine($"\n📝 Notes collected ({notes.Count}):");
    foreach (var note in notes)
    {
        Console.WriteLine($"  • {note}");
    }
}

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var topic = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(topic)
        ? "Recent advances in quantum computing"
        : topic;
}

// --- Services and Tools ---

public sealed class NoteService
{
    private readonly List<string> _notes = [];

    public void Add(string note) => _notes.Add(note);
    public IReadOnlyList<string> GetAll() => _notes.AsReadOnly();
}

public sealed class ResearchTools(NoteService noteService)
{
    [Description("Search the web for information on a query. Returns relevant search results.")]
    public async Task<string> WebSearch(
        [Description("The search query")] string query)
    {
        // Simulate web search with HttpClient (replace with a real search API in production)
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            using var http = new HttpClient();
            http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");
            var encoded = Uri.EscapeDataString(query);
            // Use DuckDuckGo instant answer API as a lightweight search
            var response = await http.GetStringAsync(
                $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1");

            if (response.Length > 3000)
                response = response[..3000];

            return string.IsNullOrWhiteSpace(response) || response == "{}"
                ? $"Search results for '{query}': No detailed results available. The topic relates to: {query}."
                : response;
        }
        catch (Exception ex)
        {
            return $"Search for '{query}' encountered an issue: {ex.Message}. " +
                   $"Please rely on your existing knowledge about this topic.";
        }
    }

    [Description("Save a research note with a key finding.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        noteService.Add(note);
        Console.WriteLine($"  📝 Note saved: {note[..Math.Min(note.Length, 60)]}...");
        return $"Note saved successfully. Total notes: {noteService.GetAll().Count}";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public string GetNotes()
    {
        var notes = noteService.GetAll();
        if (notes.Count == 0)
            return "No notes have been saved yet.";

        return "Collected notes:\n" + string.Join("\n", notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

